        return self::withOriginal(new static(0), $intervalDefinition);
    }

    $years = 0;
    $months = 0;
    $weeks = 0;
    $days = 0;
    $hours = 0;
    $minutes = 0;
    $seconds = 0;
    $milliseconds = 0;
    $microseconds = 0;

